#!/usr/bin/env node
/**
 * generate-chaos-fixtures.mjs
 *
 * Deterministic regeneration of `packages/sdk/tests/fixtures/chaos-scenarios.json`.
 *
 * The wire fixture pins the exact behavior of every registered chaos scenario
 * (draws, injection decisions, outcomes) so runtime changes fail CI loudly
 * instead of silently changing what operators rehearse.
 *
 * With `--check`, fails if the committed fixture would change (used by CI and
 * `npm run fixtures:check`).
 *
 * The fixture is generated by importing the BUILT ESM entry
 * (`dist/esm/index.js`), so it always reflects the shipped surface — run
 * `npm run build:esm` (or `npm run build`) first. Output is sorted and
 * pretty-printed with a trailing newline for canonical formatting.
 *
 * Privacy: the fixture contains scenario names, probabilities, PRNG seeds,
 * draws, and outcome labels only — never request payloads, credentials,
 * payment proofs, or secrets (see src/chaos-fixtures.ts).
 *
 * Run:  node scripts/generate-chaos-fixtures.mjs           (regenerate)
 *       node scripts/generate-chaos-fixtures.mjs --check   (CI drift check)
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const SDK_ROOT = resolve(here, "..");
const ESM_ENTRY = resolve(SDK_ROOT, "dist", "esm", "index.js");
const FIXTURE_PATH = resolve(SDK_ROOT, "tests", "fixtures", "chaos-scenarios.json");

const isCheck = process.argv.includes("--check");

if (!existsSync(ESM_ENTRY)) {
  console.error(`ESM dist not found at ${ESM_ENTRY}. Run: npm run build:esm`);
  process.exit(1);
}

let sdk;
try {
  sdk = await import(ESM_ENTRY);
} catch (err) {
  console.error(`Could not import the built ESM entry: ${err?.message ?? err}`);
  process.exit(1);
}

for (const name of ["buildChaosFixtureBundle", "CHAOS_SCENARIOS"]) {
  if (typeof sdk[name] !== "function" && sdk[name] === undefined) {
    console.error(`SDK export "${name}" missing — rebuild the ESM dist.`);
    process.exit(1);
  }
}

const bundle = sdk.buildChaosFixtureBundle();

function sortKeys(value) {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (value && typeof value === "object") {
    const out = {};
    for (const k of Object.keys(value).sort()) out[k] = sortKeys(value[k]);
    return out;
  }
  return value;
}

const canonical = JSON.stringify(sortKeys(bundle), null, 2) + "\n";

if (isCheck) {
  const current = existsSync(FIXTURE_PATH) ? readFileSync(FIXTURE_PATH, "utf8") : "";
  if (current !== canonical) {
    console.error(
      "Fixture drift: tests/fixtures/chaos-scenarios.json is stale. Run: npm run fixtures:gen",
    );
    process.exit(1);
  }
  console.log("fixtures:check ok – chaos-scenarios.json is canonical");
} else {
  writeFileSync(FIXTURE_PATH, canonical, "utf8");
  console.log(
    `fixtures:gen wrote ${FIXTURE_PATH} (${bundle.scenarios.length} scenarios, ${canonical.length} bytes)`,
  );
}
